// TH16 v1.00a Extra BossCard4 秘儀「穢那の火」
// src: st07bs.ecl.txt BossCard4:1482-1532 (entry), BossCard4_at:1534-1570 (dependency).

const TIME_LIMIT: int = 4924;      // 120 opening buffer + 4800 source window + 4 startup margin
const OPENING_BUFFER: int = 120;

// BossCard4_at EX chain (src 1537-1549), shared by emitter 0 and (via etCopy) emitter 1.
// Omitted per approved spawn-anim/visual policy: type2 ANIM a=1 (birth animation) and
// type0x100000 BRIGHT a=1. The ANIM birth offset position -= 4*velocity is kept in sh_dist.
xformdef CARD4_SHOT_FIXED {
    offscreen_keep(120);               // src type0x100 a=120 b=0
    @120 set_gravity(0fx, -0.02fx);    // src type4 a=120 r=0.02 s=-pi/2: fixed vector, 120 frames
    set_gravity(0fx, 0fx);
    wait(1);                           // src type16 STEP a=1: one tick at the old velocity
    set_angle(-90deg);                 // src STEP c=4 r=-pi/2
    set_speed(0.01fx);                 // src STEP s=0.01
    @120 set_accel(0.015fx);           // src type4 a=120 r=0.015 s=sentinel: along current angle
    set_accel(0fx);
}

// Emitter 1: etCopy(1,0) then etExSet2(1,4,...) rewrites EX record index 4 to STEP c=1.
xformdef CARD4_SHOT_AIM {
    offscreen_keep(120);
    @120 set_gravity(0fx, -0.02fx);
    set_gravity(0fx, 0fx);
    wait(1);
    set_angle(at_effect(aim_player())); // src STEP c=1: re-check the player at the segment end
    set_speed(0.01fx);
    @120 set_accel(0.015fx);
    set_accel(0fx);
}

async sub card_boss() {
    set_invuln(65535);
    set_hurtbox(20fx);                 // src Boss(): setHurtbox(40,40) -> r=20
    set_hitbox(24fx);                  // src Boss(): setHitbox(48,48) -> r=24

    // src movePosTime(180,0,0,356): (0,128) -> (0,356), mode0 linear.
    move_to(180, 0fx, 356fx, EASE_LINEAR);
    wait(180);
    // src moveLimit(0,384,240,64): boss parks at (0,356) for the whole card; limit is inert.

    sh_reset(0);
    sh_sprite(0, TH16_FIREBALL_RED, 0); // src etSprite(0,25,0)
    sh_ring(0, 0);                      // src etAim(0,3), count 1x1 -> angle0 is the shot angle
    sh_count(0, 1, 1);
    sh_speed(0, 1.5fx, 0fx);            // src etSpeed(0,1.5,1.0), one layer -> s0
    sh_dist(0, 10fx);                   // src etDist 16 + ANIM birth offset -4*1.5
    sh_xform(0, CARD4_SHOT_FIXED);

    sh_reset(1);
    sh_sprite(1, TH16_FIREBALL_RED, 0);
    sh_ring(1, 0);
    sh_count(1, 1, 1);
    sh_speed(1, 1.5fx, 0fx);
    sh_dist(1, 10fx);
    sh_xform(1, CARD4_SHOT_AIM);

    // src BossCard4_at loop: one RANDF2 draw per shot, angle = RANDF2*pi/2 + pi/2.
    // A fires at t=180+7k, B at t=183+7k. Source inner counter is 10000 (70000 frames),
    // which outlives the 4800-frame window; 660 cycles cover t=180..4800.
    for k in 0..660 {
        var ra: int = rand(65536);
        sh_angle(0, (16384 + (ra - 32768) / 2) as angle, 0deg);
        sh_fire(0);
        wait(3);
        var rb: int = rand(65536);
        sh_angle(1, (16384 + (rb - 32768) / 2) as angle, 0deg);
        sh_fire(1);
        wait(4);
    }
}

async sub card_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2700, 0, 0, 0, card_boss); // src Boss entry position (0,128)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 112, card_pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
